1	import { Page, expect } from '@playwright/test';
2	
3	export interface ArticleData {
4	  title: string;
5	  description: string;
6	  body: string;
7	  tags?: string[];
8	}
9	
10	export async function createArticle(page: Page, article: ArticleData, options: { sleepAfter?: number } = {}) {
11	  const { sleepAfter = 1 } = options;
12	
13	  await page.goto('/editor', { waitUntil: 'load' });
14	
15	  await page.fill('input[name="title"]', article.title);
16	  await page.fill('input[name="description"]', article.description);
17	  await page.fill('textarea[name="body"]', article.body);
18	
19	  if (article.tags && article.tags.length > 0) {
20	    for (const tag of article.tags) {
21	      await page.fill('input[placeholder="Enter tags"]', tag);
22	      await page.press('input[placeholder="Enter tags"]', 'Enter');
23	    }
24	  }
25	
26	  // Start waiting for navigation before clicking to avoid race condition
27	  await Promise.all([page.waitForURL(/\/article\/.+/), page.click('button:has-text("Publish Article")')]);
28	
29	  // Ensure Date.now() advances so the next generateUniqueArticle() gets a distinct timestamp
30	  if (sleepAfter > 0) {
31	    await new Promise(resolve => setTimeout(resolve, sleepAfter));
32	  }
33	}
34	
35	export async function editArticle(page: Page, slug: string, updates: Partial<ArticleData>) {
36	  await page.goto(`/editor/${slug}`, { waitUntil: 'load' });
37	
38	  // Wait for the API data to populate the form (not just for the input to exist)
39	  const titleInput = page.locator('input[name="title"]');
40	  await expect(titleInput).not.toHaveValue('', { timeout: 10000 });
41	
42	  if (updates.title) {
43	    await page.fill('input[name="title"]', '');
44	    await page.fill('input[name="title"]', updates.title);
45	  }
46	  if (updates.description) {
47	    await page.fill('input[name="description"]', '');
48	    await page.fill('input[name="description"]', updates.description);
49	  }
50	  if (updates.body) {
51	    await page.fill('textarea[name="body"]', '');
52	    await page.fill('textarea[name="body"]', updates.body);
53	  }
54	
55	  await Promise.all([page.waitForURL(/\/article\/.+/), page.click('button:has-text("Publish Article")')]);
56	}
57	
58	export async function deleteArticle(page: Page) {
59	  // Assumes we're already on the article page
60	  await Promise.all([page.waitForURL('/'), page.click('button:has-text("Delete Article")')]);
61	}
62	
63	export async function favoriteArticle(page: Page) {
64	  await page.click('button.btn-outline-primary:has-text("Favorite")');
65	  // Wait for the button to update to "Unfavorite"
66	  await page.waitForSelector('button.btn-primary:has-text("Unfavorite")');
67	}
68	
69	export async function unfavoriteArticle(page: Page) {
70	  await page.click('button.btn-primary:has-text("Unfavorite")');
71	  // Wait for the button to update back to "Favorite"
72	  await page.waitForSelector('button.btn-outline-primary:has-text("Favorite")');
73	}
74	
75	export function generateUniqueArticle(): ArticleData {
76	  const timestamp = Date.now();
77	  return {
78	    title: `Test Article ${timestamp}`,
79	    description: `Description for test article ${timestamp}`,
80	    body: `This is the body content for test article created at ${timestamp}. It contains enough text to be meaningful.`,
81	    tags: ['test', 'playwright'],
82	  };
83	}
