    except User.DoesNotExist:
        return render(request, "accounts/profile_404.html", {"username": username}, status=404)

    try:
        page = int(request.GET.get("page", 1))
    except (ValueError, TypeError):
        page = 1
    offset = (page - 1) * ARTICLES_PER_PAGE

